"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raises the CPU limit for the 'api' container to 750m, reducing throttling and improving readiness probe success rates.",
  "rationale": "The container is consistently hitting its CPU limit (0.5) with 0.498 usage, and throttling is 58%. Raising the limit to 750m (1.5x current) should clear the throttling without affecting memory or other resources. Earlier revision health is unknown, but the recent rollout suggests the new version may use more CPU than before, making this a valid adjustment.",
